function dmRedraw(C){
  if(DM_CTX !== C) return;
  const sat0 = C.A ? dmSatWhy(C) : '';
  C.r = dmGet(C.inX); C.prov = false; C.A = dmAnsOf(C.plan, C.plan.k, C.r);
  // the list's "Nothing here changes this" (and each row's reason for no change) was said from the quick games: said again from
  // the answer's own 10,000 when they disagree (2,000 games can wipe the target in 99.5% where 10,000 do in 99.4%)
  const host = $('#dmList');
  if(host && (C.A ? dmSatWhy(C) : '') !== sat0){
    // drawn again as the player left it: the folds opened since the screen was drawn (dmState's, not the screen's copy of it), the
    // focus, and, when the note was above the top of the screen, the rows where they were
    C.st.fold = Object.assign({}, dmState().fold);
    const ae = document.activeElement, fid = ae && host.contains(ae) && ae.dataset ? ae.dataset.dmlv : null;
    const topY = $('#top').getBoundingClientRect().bottom, note = host.querySelector('.dmsat');
    const vis = !dmAnchor && note && note.getBoundingClientRect().bottom <= topY ? [...host.querySelectorAll('[data-dmlv]')].find(e => e.getClientRects().length && e.getBoundingClientRect().top >= topY) : null;
    const vid = vis ? vis.dataset.dmlv : null, vtop = vis ? vis.getBoundingClientRect().top : 0;
    host.innerHTML = dmListHtml(C); for(const lv of C.levers) if(lv.fx || lv.est) dmPatch(C, lv, !lv.fx);
    const at = id => id && host.querySelector('[data-dmlv="' + CSS.escape(id) + '"]');
    const fe = at(fid); if(fe) fe.focus({ preventScroll:true });
    const ve = at(vid); if(ve && ve.getClientRects().length){ const d = ve.getBoundingClientRect().top - vtop; if(Math.abs(d) >= 1) scrollBy(0, d); } }
  const a = $('#dmAns');
  if(a){ const h0 = a.offsetHeight, t = document.createElement('template'); t.innerHTML = dmCard(C); const n = t.content.firstElementChild;
    const keys = e => [...e.querySelectorAll('[data-dmc]')].map(x => x.dataset.dmc).join('|');
    if(keys(a) === keys(n)){ a.classList.remove('prov'); for(const x of n.querySelectorAll('[data-dmc]')){ const o = a.querySelector('[data-dmc="' + x.dataset.dmc + '"]'); if(o.innerHTML !== x.innerHTML) o.innerHTML = x.innerHTML;
      if(x.hasAttribute('aria-label')) o.setAttribute('aria-label', x.getAttribute('aria-label')); } }
    else { a.outerHTML = n.outerHTML; dmChipCap(); }
    const a2 = $('#dmAns'); if(a2.offsetHeight < h0) a2.style.minHeight = h0 + 'px'; }
  dmStick();
  // the profile picked shows the answer itself: now from its own 10,000 games
  for(const lv of C.levers) if(lv.sec === 'prof' && lv.on) for(const el of document.querySelectorAll('[data-fx="' + CSS.escape(lv.id) + '"]')) el.innerHTML = dmFxHtml(C, lv);
  dmAnchorKeep();
}

document.addEventListener('toggle', e => {
  const d = e.target;
  if(!d.dataset) return;
  if(d.hasAttribute('data-dmfold')){ dmState().fold[d.dataset.dmfold] = d.open; saveSession();   // the Damage tab's folds stay as left
    if(DM_CTX) DM_CTX.st.fold[d.dataset.dmfold] = d.open;   // (and in the screen's copy, which a list drawn again in the background draws from)
    if(d.open) for(const w of d.querySelectorAll('.dwv[data-wh]')) w.scrollTop = +w.dataset.i * WH_ROW;   // (a wheel drawn folded takes its row once shown)
    return; }
  if(d.dataset.ckfold){ if(d.open) openStrats.add(d.dataset.ckfold); else openStrats.delete(d.dataset.ckfold); saveSession(); return; }   // a Phase checklist fold
  if(d.dataset.tgfold){ if(d.open) openStrats.add(d.dataset.tgfold); else openStrats.delete(d.dataset.tgfold); saveSession(); return; }   // a datasheet's When targeted fold
  if(d.dataset.stratId){
    if(d.open) openStrats.add(d.dataset.stratId); else openStrats.delete(d.dataset.stratId);
    saveSession();
    const x = $('#view [data-expand]');
    if(x) x.textContent = $$('#view details.strat').every(c => c.open) ? 'Collapse all' : 'Expand all';
  }
}, true);
