document.addEventListener('change', e => {
  if(e.target.id !== 'impFile' || !e.target.files || !e.target.files[0]) return;
  const f = e.target.files[0];
  f.text().then(t => { const box = $('#impText'); if(box) box.value = ''; runImport(t); }, () => { const out = $('#impOut'); if(out) out.innerHTML = '<div class="impno"><p class="qh">Not imported</p><p class="lead">The file could not be read.</p></div>'; });
});
